      "explanation": [
        "Galvenā doma: Laika apstāklis ​​​​​​ar mazo burtu. Nozīmē nākamo dienu — ride.",
        "Domani galvenokārt nozīmē: nākamajā dienā.",
        "Biezi raksturo: laika apstāklis.",
        "Domani significa principalmente: parte della giornata.",
        "Biezi raksturo: Laatvārds (der).",
        "Domani galvenokārt nozīmē: vairāki rīti.",
        "Bieži raksturo: Laatvārds (pl.).",
        "Morgen ar mazo sākumburtu nozīmē rīt — nākamajā dienā (Ich komme morgen = es nāku rīt, Bis morgen!"
      ],
