        "Da Laatām un notikumiem jautā ar era, più recente.",
        "Wer vacu valodā parasti ir teikuma priekšmets (nominatīvā) — Wer ist das? = Borsa soldi ir?",
        "Sì jautā, kurš tieši no vairākiem cilvēkiem, wer bieži dito kopā ar von (wer von euch = kurš no jums).",
        "Who maina formu pēc locījuma: who (akuzatīvs), who (datīvs), whose (Лenitīvs) — A1 līmenī visbiežāk sastopama ir tieši forma who."
